import { CommonModule, DOCUMENT } from '@angular/common';
import {
  ChangeDetectionStrategy,
  Component,
  HostListener,
  Inject,
  Renderer2,
  signal,
} from '@angular/core';

interface NavigationItem {
  label: string;
  target: string;
}

interface SolutionCard {
  eyebrow: string;
  title: string;
  description: string;
  headline: string;
  promise: string;
  result: string;
  image: string;
  voiceCommand: string;
  price: string;
  products: string[];
  outcomes: string[];
  featuredProducts?: ComboFeaturedProduct[];
}

interface ComboFeaturedProduct {
  label: string;
  description: string;
  image: string;
  x: number;
  y: number;
}

interface ProductCategory {
  title: string;
  description: string;
}

interface Benefit {
  icon: string;
  title: string;
  description: string;
}

@Component({
  selector: 'app-landing',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './landing.component.html',
  styleUrl: './landing.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class LandingComponent {
  protected readonly isScrolled = signal(false);
  protected readonly isMenuOpen = signal(false);
  protected readonly activeSolutionIndex = signal(0);

  private readonly whatsappPhone = '5493512517479';

  protected readonly whatsappUrl = this.createWhatsappUrl(
    'Hola ModoConectado, quiero recibir información para automatizar mi espacio.',
  );

  protected readonly navItems: NavigationItem[] = [
    { label: 'Inicio', target: 'inicio' },
    { label: 'Soluciones', target: 'soluciones' },
    { label: 'Combos', target: 'combos' },
    { label: 'Sobre nosotros', target: 'sobre-nosotros' },
    { label: 'Contacto', target: 'contacto' },
  ];

  protected readonly solutions: SolutionCard[] = [
    {
      eyebrow: 'Smart Home',
      title: 'Casa',
      description: 'Alexa, focos, sensores y cámaras.',
      headline: 'Tu casa inteligente. Tu vida más simple.',
      promise: 'Automatizá los ambientes principales y controlá seguridad, luces y rutinas desde un solo lugar.',
      result: 'Ideal para empezar con una casa conectada sin instalaciones invasivas.',
      image: 'assets/images/solution-home-alexa-security.jpg',
      voiceCommand: 'Alexa, llegué a casa',
      price: '$450.000',
      products: [
        '1 Alexa',
        '5 focos smart',
        '1 cámara interna',
        '1 cámara externa',
        '2 sensores',
        '1 control smart',
        '2 interruptores',
      ],
      outcomes: ['Luces encendidas', 'Cámaras monitoreando', 'Sensores activos', 'Todo desde tu celular'],
      featuredProducts: [
        {
          label: '1 Alexa',
          description: 'Activá escenas completas con comandos de voz simples.',
          image: 'assets/images/Alexa.png',
          x: 20,
          y: 67,
        },
        {
          label: '5 focos',
          description: 'Controlá la iluminación de los ambientes principales desde el celular.',
          image: 'assets/images/foco.png',
          x: 44,
          y: 28,
        },
        {
          label: '1 cámara interna',
          description: 'Mirá lo que pasa dentro de tu casa en tiempo real.',
          image: 'assets/images/camaraInterna.png',
          x: 67,
          y: 42,
        },
        {
          label: '1 cámara externa',
          description: 'Sumá monitoreo en accesos, patio o ingreso principal.',
          image: 'assets/images/camaraExterna.png',
          x: 77,
          y: 20,
        },
        {
          label: '2 sensores',
          description: 'Recibí alertas por movimiento, puertas o ventanas según la instalación.',
          image: 'assets/images/sensor.png',
          x: 33,
          y: 51,
        },
        {
          label: '1 control',
          description: 'Centralizá TV, aire y equipos compatibles en una sola app.',
          image: 'assets/images/control.png',
          x: 73,
          y: 73,
        },
        {
          label: '2 interruptores',
          description: 'Automatizá luces o circuitos sin perder el uso manual.',
          image: 'assets/images/interruptor.png',
          x: 45,
          y: 76,
        },
      ],
    },
    {
      eyebrow: 'Smart Home',
      title: 'Departamento',
      description: 'Alexa, cámaras y escenas inteligentes.',
      headline: 'Tu departamento automatizado y más cómodo.',
      promise: 'Controlá luces, voz y entretenimiento sin complicarte con instalaciones grandes.',
      result: 'Perfecto para sumar confort rápido en espacios compactos.',
      image: 'assets/images/solution-apartment-alexa-security.jpg',
      voiceCommand: 'Alexa, modo descanso',
      price: '$220.000',
      products: ['1 Alexa', '5 focos smart', '1 control smart'],
      outcomes: ['Control por voz', 'Automatización inteligente', 'Mayor comodidad', 'Todo desde una sola app'],
      featuredProducts: [
        {
          label: '1 Alexa',
          description: 'Controlá luces, escenas y rutinas usando solo tu voz.',
          image: 'assets/images/Alexa.png',
          x: 68,
          y: 68,
        },
        {
          label: '5 focos smart',
          description: 'Apagá, encendé y regulá las luces desde donde estés.',
          image: 'assets/images/foco.png',
          x: 52,
          y: 28,
        },
        {
          label: '1 control',
          description: 'Manejás TV, aire y equipos compatibles desde una sola app.',
          image: 'assets/images/control.png',
          x: 22,
          y: 62,
        },
      ],
    },
    {
      eyebrow: 'Smart Business',
      title: 'Negocios',
      description: 'Monitoreo, alarmas y control por voz.',
      headline: 'Tu negocio no depende de que estés presente.',
      promise: 'Monitoreá, encendé luces y recibí alertas desde el celular cuando no estás.',
      result: 'Pensado para operar con más control y menos preocupación diaria.',
      image: 'assets/images/solution-business-alexa-security.jpg',
      voiceCommand: 'Alexa, activar modo negocio',
      price: '$420.000',
      products: [
        '1 Alexa',
        '2 interruptores',
        '1 cámara externa',
        '1 cámara interna',
        '2 sensores',
        '3 focos smart',
        '1 control smart',
      ],
      outcomes: ['Mirá tu negocio en tiempo real', 'Controlá las luces', 'Recibí alertas', 'Activá funciones con Alexa'],
      featuredProducts: [
        {
          label: '1 Alexa',
          description: 'Activá rutinas de apertura, cierre o seguridad con comandos de voz.',
          image: 'assets/images/Alexa.png',
          x: 18,
          y: 66,
        },
        {
          label: '2 interruptores',
          description: 'Automatizá luces o circuitos clave sin perder el control manual.',
          image: 'assets/images/interruptor.png',
          x: 42,
          y: 72,
        },
        {
          label: '1 cámara externa',
          description: 'Controlá accesos, vidriera o entrada desde tu celular.',
          image: 'assets/images/camaraExterna.png',
          x: 76,
          y: 24,
        },
        {
          label: '1 cámara interna',
          description: 'Supervisá atención, caja o movimiento dentro del local.',
          image: 'assets/images/camaraInterna.png',
          x: 66,
          y: 45,
        },
        {
          label: '2 sensores',
          description: 'Recibí alertas ante aperturas o movimientos fuera de horario.',
          image: 'assets/images/sensor.png',
          x: 34,
          y: 48,
        },
        {
          label: '3 focos',
          description: 'Programá iluminación para atención, cierre o ahorro de energía.',
          image: 'assets/images/foco.png',
          x: 50,
          y: 28,
        },
        {
          label: '1 control',
          description: 'Centralizá aire, TV u otros equipos compatibles desde una app.',
          image: 'assets/images/control.png',
          x: 74,
          y: 72,
        },
      ],
    },
  ];

  protected readonly productCategories: ProductCategory[] = [
    {
      title: 'Alexa Echo Dot',
      description: 'Control por voz para luces, escenas y rutinas.',
    },
    {
      title: 'Focos inteligentes',
      description: 'Iluminación regulable y programable por ambientes.',
    },
    {
      title: 'Controles remotos',
      description: 'Centralizá TV, aire y equipos compatibles.',
    },
    {
      title: 'Cámaras de seguridad',
      description: 'Interior y exterior con monitoreo desde el celular.',
    },
    {
      title: 'Módulos para interruptores',
      description: 'Automatización oculta sin cambiar la estética.',
    },
    {
      title: 'Sensores de apertura',
      description: 'Alertas para puertas, ventanas y accesos.',
    },
  ];

  protected readonly benefits: Benefit[] = [
    {
      icon: 'tool',
      title: 'Instalación profesional',
      description: 'Técnicos especializados.',
    },
    {
      icon: 'gear',
      title: 'Configuración incluida',
      description: 'Dejamos todo listo para usar.',
    },
    {
      icon: 'headset',
      title: 'Soporte personalizado',
      description: 'Te acompañamos siempre.',
    },
    {
      icon: 'shield',
      title: 'Garantía total',
      description: 'Productos y servicio garantizados.',
    },
  ];

  constructor(
    @Inject(DOCUMENT) private readonly document: Document,
    private readonly renderer: Renderer2,
  ) {
    this.updateScrollState();
  }

  @HostListener('window:scroll')
  protected onWindowScroll(): void {
    this.updateScrollState();
  }

  protected toggleMenu(): void {
    this.isMenuOpen.update((isOpen) => {
      const nextState = !isOpen;
      this.syncBodyMenuState(nextState);
      return nextState;
    });
  }

  protected closeMenu(): void {
    if (!this.isMenuOpen()) {
      return;
    }

    this.isMenuOpen.set(false);
    this.syncBodyMenuState(false);
  }

  protected setActiveSolution(index: number): void {
    this.activeSolutionIndex.set(index);
  }

  protected activeSolution(): SolutionCard {
    return this.solutions[this.activeSolutionIndex()] ?? this.solutions[0];
  }

  protected comboWhatsappUrl(solution: SolutionCard): string {
    return this.createWhatsappUrl(
      `Hola ModoConectado, quiero cotizar el combo para ${solution.title}. Me interesa automatizar con Alexa, cámaras y dispositivos inteligentes.`,
    );
  }

  private updateScrollState(): void {
    this.isScrolled.set(this.document.defaultView?.scrollY ? this.document.defaultView.scrollY > 12 : false);
  }

  private createWhatsappUrl(message: string): string {
    return `https://wa.me/${this.whatsappPhone}?text=${encodeURIComponent(message)}`;
  }

  private syncBodyMenuState(isOpen: boolean): void {
    if (isOpen) {
      this.renderer.addClass(this.document.body, 'menu-open');
      return;
    }

    this.renderer.removeClass(this.document.body, 'menu-open');
  }
}
<header class="site-header" [class.site-header--scrolled]="isScrolled()">
  <a class="brand" href="#inicio" aria-label="Ir al inicio" (click)="closeMenu()">
    <span class="brand__mark" aria-hidden="true">
      <svg xmlns="http://www.w3.org/2000/svg" viewBox="35 25 790 195">
        <g fill="none" stroke="#B7FF00" stroke-width="18" stroke-linecap="round" stroke-linejoin="round">
         <path d="M55 112 L130 48 L205 112 V190 H157 V143 H103 V190 H55 Z"/>
         <path d="M95 111 Q130 78 165 111"/><path d="M108 128 Q130 108 152 128"/><circle cx="130" cy="146" r="5" fill="#B7FF00" stroke="none"/>
        </g>
        <text x="245" y="105" font-family="Arial,Helvetica,sans-serif" font-size="66" font-weight="800" fill="#FFFFFF">MODO</text>
        <text x="245" y="170" font-family="Arial,Helvetica,sans-serif" font-size="66" font-weight="800" fill="#B7FF00">CONECTADO</text>
        <text x="248" y="204" font-family="Arial,Helvetica,sans-serif" font-size="18" font-weight="600" letter-spacing="7" fill="#FFFFFF">AUTOMATIZACIÓN INTELIGENTE</text>
       </svg>
    </span>
  </a>

  <nav class="nav" [class.nav--open]="isMenuOpen()" aria-label="Navegación principal">
    <a
      *ngFor="let item of navItems; first as isFirst"
      [class.nav__link--active]="isFirst"
      class="nav__link"
      [href]="'#' + item.target"
      (click)="closeMenu()"
    >
      {{ item.label }}
    </a>
  </nav>

  <a class="quote-link" [href]="whatsappUrl" target="_blank" rel="noreferrer">
    Cotizá ahora
    <span aria-hidden="true">↗</span>
  </a>

  <button
    class="menu-button"
    type="button"
    [attr.aria-expanded]="isMenuOpen()"
    aria-label="Abrir menú"
    (click)="toggleMenu()"
  >
    <span></span>
    <span></span>
  </button>
</header>

<main>
  <section id="inicio" class="hero section-anchor">
    <div class="hero__image" aria-hidden="true"></div>
    <div class="hero__shade" aria-hidden="true"></div>

    <div class="hero__content page-shell">
      <p class="eyebrow">Tecnología que se adapta a tu vida</p>
      <h1>Automatizá tu casa <span>o negocio.</span></h1>
      <p class="hero__lead">
        Controlá luces, cámaras, cerraduras y más desde Alexa, tu celular o con tu voz.
      </p>
      <p class="hero__support">Viví más cómodo, seguro y conectado.</p>

      <div class="hero__actions">
        <a class="button button--primary" [href]="whatsappUrl" target="_blank" rel="noreferrer">
          <svg class="whatsapp-icon" viewBox="0 0 32 32" aria-hidden="true">
            <path class="whatsapp-icon__bubble" d="M16 3.2A12.7 12.7 0 0 0 5.1 22.4L3.6 28.8l6.6-1.5A12.7 12.7 0 1 0 16 3.2Z" />
            <path class="whatsapp-icon__phone" d="M22.9 18.9c-.4-.2-2.2-1.1-2.6-1.2-.3-.1-.6-.2-.9.2-.3.4-1 1.2-1.2 1.4-.2.3-.4.3-.8.1-.4-.2-1.5-.6-2.9-1.8-1.1-1-1.8-2.1-2-2.5-.2-.4 0-.6.2-.8l.6-.7c.2-.2.3-.4.4-.7.1-.2.1-.5 0-.7-.1-.2-.9-2.1-1.2-2.9-.3-.7-.6-.6-.9-.6h-.8c-.3 0-.7.1-1.1.5-.4.4-1.4 1.4-1.4 3.3s1.5 3.8 1.7 4.1c.2.3 2.8 4.4 6.9 6.1 1 .4 1.7.7 2.3.8 1 .3 1.8.2 2.5.2.8-.1 2.2-.9 2.5-1.8.3-.9.3-1.7.2-1.9-.1-.3-.4-.4-.8-.6Z" />
          </svg>
          Cotizá por WhatsApp
        </a>
        <a class="button button--secondary" href="#soluciones">
          Ver soluciones
          <span aria-hidden="true">⌄</span>
        </a>
      </div>
    </div>
  </section>

  <section class="compatibility" aria-label="Tecnología compatible">
    <div class="page-shell compatibility__inner">
      <p>Tecnología compatible con</p>
      <div class="compatibility__logos">
        <span>alexa</span>
        <span>Google Home</span>
        <span>tuya</span>
        <span>Smart Life</span>
      </div>
    </div>
  </section>

  <section id="soluciones" class="solutions section-anchor page-shell">
    <div class="section-copy">
      <p class="eyebrow eyebrow--green">Combos inteligentes</p>
      <h2>Elegí el escenario. Nosotros armamos la experiencia.</h2>
      <p>Soluciones listas para instalar, configurar y controlar con Alexa o desde tu celular.</p>
      <a class="button button--ghost" href="#contacto">
        Cotizar combo
        <span aria-hidden="true">→</span>
      </a>
    </div>

    <div class="combo-explorer">
      <div class="combo-tabs" role="tablist" aria-label="Combos disponibles">
        <button
          *ngFor="let solution of solutions; let index = index"
          type="button"
          class="combo-tab"
          [class.combo-tab--active]="activeSolutionIndex() === index"
          [attr.aria-selected]="activeSolutionIndex() === index"
          (click)="setActiveSolution(index)"
        >
          <span>{{ solution.eyebrow }}</span>
          <strong>{{ solution.title }}</strong>
          <small>{{ solution.description }}</small>
        </button>
      </div>

      <article class="combo-panel">
        <div class="combo-panel__image">
          <img [src]="activeSolution().image" [alt]="'Combo para ' + activeSolution().title">
          <div
            *ngIf="activeSolution().featuredProducts?.length"
            class="combo-highlights"
            [class.combo-highlights--dense]="(activeSolution().featuredProducts?.length ?? 0) > 4"
            aria-label="Productos incluidos destacados"
          >
            <button
              *ngFor="let product of activeSolution().featuredProducts"
              type="button"
              class="combo-highlight"
              [class.combo-highlight--align-start]="product.x < 30"
              [class.combo-highlight--align-end]="product.x > 64"
              [class.combo-highlight--tooltip-top]="product.y > 52"
              [style.left.%]="product.x"
              [style.top.%]="product.y"
              [attr.aria-label]="product.label + '. ' + product.description"
            >
              <span class="combo-highlight__media">
                <img [src]="product.image" alt="">
              </span>
              <strong>{{ product.label }}</strong>
              <span class="combo-highlight__description">{{ product.description }}</span>
            </button>
          </div>
        </div>
        <div class="combo-panel__content">
          <p class="combo-panel__eyebrow">{{ activeSolution().eyebrow }} · Combo {{ activeSolution().title }}</p>
          <h3>{{ activeSolution().headline }}</h3>
          <p class="combo-panel__promise">{{ activeSolution().promise }}</p>

          <div class="voice-command">
            <span aria-hidden="true"></span>
            <div>
              <small>Escena sugerida</small>
              <strong>“{{ activeSolution().voiceCommand }}”</strong>
            </div>
          </div>

          <div class="combo-kit">
            <p>Kit incluido</p>
            <div class="combo-kit__items">
              <span *ngFor="let product of activeSolution().products">{{ product }}</span>
            </div>
          </div>

          <p class="combo-panel__result">{{ activeSolution().result }}</p>

          <div class="combo-panel__footer">
            <div>
              <span>Desde</span>
              <strong>{{ activeSolution().price }}</strong>
            </div>
            <a class="button button--primary" [href]="comboWhatsappUrl(activeSolution())" target="_blank" rel="noreferrer">
              Cotizá este combo
            </a>
          </div>
        </div>
      </article>
    </div>
  </section>

  <section id="combos" class="products section-anchor page-shell">
    <div class="products__media" aria-hidden="true"></div>
    <div class="products__content">
      <p class="eyebrow eyebrow--green">Productos inteligentes</p>
      <h2>Todo lo necesario para automatizar de verdad.</h2>
      <p>
        Combinamos dispositivos disponibles con instalación y configuración para crear sistemas completos,
        no compras sueltas difíciles de usar.
      </p>

      <div class="product-list" aria-label="Productos disponibles">
        <article class="product-item" *ngFor="let product of productCategories">
          <h3>{{ product.title }}</h3>
          <p>{{ product.description }}</p>
        </article>
      </div>
    </div>
  </section>

  <section id="control" class="control section-anchor page-shell">
    <div class="control__copy">
      <p class="eyebrow eyebrow--green">Control total</p>
      <h2>Todo desde tu celular.</h2>
      <p>Una sola app y Alexa para controlar tus dispositivos desde donde estés.</p>

      <ul class="check-list" aria-label="Funcionalidades principales">
        <li>Encendé y apagá luces</li>
        <li>Revisá cámaras en tiempo real</li>
        <li>Activá modos y escenas</li>
        <li>Recibí alertas al instante</li>
      </ul>

      <a class="button button--ghost" href="#contacto">
        Ver cómo funciona
        <span aria-hidden="true">→</span>
      </a>
    </div>
    <div class="control__visual" aria-hidden="true"></div>
  </section>

  <section class="benefits page-shell" aria-label="Servicios incluidos">
    <article class="benefit" *ngFor="let benefit of benefits">
      <span class="benefit__icon" [attr.data-icon]="benefit.icon" aria-hidden="true"></span>
      <div>
        <h3>{{ benefit.title }}</h3>
        <p>{{ benefit.description }}</p>
      </div>
    </article>
  </section>

  <section id="contacto" class="cta section-anchor page-shell">
    <div>
      <p class="eyebrow eyebrow--green">Estás a un paso de vivir inteligente</p>
      <h2>Transformá tu espacio hoy.</h2>
      <p>Solicitá tu presupuesto sin compromiso.</p>
    </div>
    <div class="cta__action">
      <a class="button button--primary" [href]="whatsappUrl" target="_blank" rel="noreferrer">
        <svg class="whatsapp-icon" viewBox="0 0 32 32" aria-hidden="true">
          <path class="whatsapp-icon__bubble" d="M16 3.2A12.7 12.7 0 0 0 5.1 22.4L3.6 28.8l6.6-1.5A12.7 12.7 0 1 0 16 3.2Z" />
          <path class="whatsapp-icon__phone" d="M22.9 18.9c-.4-.2-2.2-1.1-2.6-1.2-.3-.1-.6-.2-.9.2-.3.4-1 1.2-1.2 1.4-.2.3-.4.3-.8.1-.4-.2-1.5-.6-2.9-1.8-1.1-1-1.8-2.1-2-2.5-.2-.4 0-.6.2-.8l.6-.7c.2-.2.3-.4.4-.7.1-.2.1-.5 0-.7-.1-.2-.9-2.1-1.2-2.9-.3-.7-.6-.6-.9-.6h-.8c-.3 0-.7.1-1.1.5-.4.4-1.4 1.4-1.4 3.3s1.5 3.8 1.7 4.1c.2.3 2.8 4.4 6.9 6.1 1 .4 1.7.7 2.3.8 1 .3 1.8.2 2.5.2.8-.1 2.2-.9 2.5-1.8.3-.9.3-1.7.2-1.9-.1-.3-.4-.4-.8-.6Z" />
        </svg>
        Cotizá por WhatsApp
      </a>
      <small>Respuesta rápida garantizada ⚡</small>
    </div>
  </section>
</main>

<footer id="sobre-nosotros" class="footer section-anchor page-shell">
  <a class="brand" href="#inicio" aria-label="Ir al inicio">
    <span class="brand__mark" aria-hidden="true">
      <svg viewBox="0 0 32 32">
        <path d="M4.5 13.8 16 5l11.5 8.8V27h-7.3v-9.4h-8.4V27H4.5V13.8Z" />
        <path d="M12.1 27v-9.4h7.8V27" />
